import {regions,project} from './coastal-geography.js';
import {regionShapes} from './coastal-boundaries.js';
import {countryLearning,flagUrl} from './coastal-learning.js';
import {stationArt,stationArtUrl} from './coastal-station-art.js';
import {lineColour} from './coastal-lines.js';

import {expedition,recordKnowledge} from './coastal-expedition.js';
import {mapLandmarks} from './coastal-landmarks.js';
const asset=name=>new URL('../assets/coastal/passport/'+name+'.png',import.meta.url).href;
export function renderPassportReview({content,state,review,region,question,stops,lineStops,node,makeButton,refresh,close}){
 const country=regions.find(r=>r.id===region),learning=countryLearning[region],capital=stops.find(s=>s.region===region&&s.capital),art=stationArt[capital.id];
 content.className='coastal-passport';content.replaceChildren();
 const left=node('section',null,'coastal-passport-page coastal-passport-left'),right=node('section',null,'coastal-passport-page coastal-passport-right');
 const mast=node('header',null,'coastal-passport-mast'),compass=node('img');compass.src=asset('passport-compass');compass.alt='';mast.append(compass,node('div'));mast.lastChild.append(node('span','EXPEDITION PASSPORT'),node('small','PLACES · PEOPLE · TRANSPORT'));left.append(mast,node('h3','Round '+state.round+(state.complete?' complete!':' field notes')));
 const stars=node('div','★'.repeat(state.complete?state.stars??0:0)+'☆'.repeat(state.complete?3-(state.stars??0):3),'coastal-passport-stars');stars.setAttribute('aria-label',state.complete?(state.stars??0)+' out of 3 stars':'Round in progress');left.append(stars,node('p',state.complete?'Great work! You connected places, moved people and explored our world.':'Explore your network and collect geography notes as you travel.','coastal-passport-welcome'));
 const postcard=node('figure',null,'coastal-passport-photo'),picture=node('img');picture.src=stationArtUrl(capital.id);picture.alt=art.landmark+' in '+country.capital;postcard.append(picture,node('figcaption',art.landmark+' · '+country.capital));
 const stamp=node('div',null,'coastal-passport-stamp'),flag=node('img');flag.src=flagUrl(region);flag.alt=region==='northern-ireland'?'Union Flag of the United Kingdom':country.name+' flag';stamp.append(node('strong',country.name),flag,node('small','EXPLORE · LEARN · CONNECT'));postcard.append(stamp);left.append(postcard);
 const discovery=node('section',null,'coastal-passport-discovery');discovery.append(node('span','GEOGRAPHY DISCOVERY'),node('h4',country.name+' explorer'),node('p',learning.setting),node('strong','★ Capital · '+country.capital),node('small','✓ UNLOCKED IN YOUR PASSPORT'));left.append(discovery,node('p','Same places. Brighter minds.','coastal-passport-motto'));
 right.append(node('h4','YOUR ROUND STATISTICS','coastal-passport-heading'));const tags=node('div',null,'coastal-passport-tags');
 for(const [icon,value,label]of [['♟',state.delivered,'passengers delivered'],['◷',review.longestWait+'s','longest wait'],['▥',review.busiest?.name??'—','busiest city']]){const tag=node('article',null,'coastal-passport-tag');tag.append(node('span',icon),node('strong',String(value)),node('small',label));if(label==='busiest city'&&review.busiest)tag.append(node('small','Peak queue · '+review.busiest.queue));tags.append(tag);}right.append(tags);
 const network=node('div',null,'coastal-passport-network'),route=node('section',null,'coastal-passport-route');route.append(node('h4','YOUR ROUTE THIS ROUND'));route.append(routeSketch(state,review.best,stops,lineStops,node));route.append(node('p',review.best?review.best.stops.map(id=>stops[id].name).join(' → '):'Connect cities to draw your first journey here.'));if(review.best)route.append(node('small','Best line · '+review.best.delivered+' delivered · '+review.best.credits+' 💷'));const tip=node('aside',null,'coastal-passport-tip');tip.append(node('span','☀'),node('h4','NETWORK TIP'),node('p',review.tip));network.append(route,tip);right.append(network);
 const spotlight=node('section',null,'coastal-passport-spotlight');spotlight.append(node('span','✦ LEARNING SPOTLIGHT'),node('h4','Discover '+country.name),node('p',learning.extra[0]??country.facts[0]),node('small','Waterways · '+learning.water));right.append(spotlight);
 const quiz=node('section',null,'coastal-passport-quiz');quiz.append(node('h4','? GEOGRAPHY BONUS'),node('p',question.prompt));const choices=node('div',null,'coastal-passport-answers'),answer=node('p',null,'coastal-passport-answer'),notes=node('details',null,'coastal-passport-notes');notes.append(node('summary','Learn more'),node('p',question.explanation));const source=node('a','Read on Wikipedia ↗');source.href=question.source??learning.source??country.source;source.target='_blank';source.rel='noopener';notes.append(source);
 for(const choice of [...question.options].sort((a,b)=>a.localeCompare(b))){const button=makeButton(choice,()=>{if(state.reviewQuiz||!state.complete)return;const correct=choice===question.options[0];state.reviewQuiz={correct,answer:choice};if(correct){state.credits+=5;recordKnowledge(state,region);}answer.textContent=correct?'Correct! +5 💷':'The answer is '+question.options[0]+'.';answer.dataset.correct=String(correct);for(const b of choices.children){b.disabled=true;b.dataset.correct=String(b.dataset.reviewAnswer===question.options[0]);}notes.hidden=false;refresh();});button.dataset.reviewAnswer=choice;button.disabled=Boolean(state.reviewQuiz)||!state.complete;if(state.reviewQuiz)button.dataset.correct=String(choice===question.options[0]);choices.append(button);}
 if(state.reviewQuiz){answer.textContent=state.reviewQuiz.correct?'Correct! Geography bonus collected.':'The answer is '+question.options[0]+'.';answer.dataset.correct=String(state.reviewQuiz.correct);}else if(!state.complete)answer.textContent='Finish this round to answer for +5 💷.';else answer.textContent='One answer · Correct = +5 💷';notes.hidden=!state.reviewQuiz;quiz.append(choices,answer,notes);right.append(quiz);
 const e=expedition(state),newStamps=Object.values(e.stamps).filter(s=>s.round===state.round).length;right.append(node('p','✦ Passport discoveries this round: '+newStamps+' stamps · '+e.missions.filter(m=>m.claimed).length+' / 3 geography missions completed.','coastal-passport-spotlight'));const discoveries=node('details',null,'coastal-passport-notes');discoveries.append(node('summary','Your new geography stamps'));for(const l of mapLandmarks.filter(l=>e.stamps[l.id]?.round===state.round))discoveries.append(node('p',l.name+' · '+regions.find(r=>r.id===l.region).name));if(!newStamps)discoveries.append(node('p','Deliver passengers to cities and answer geography questions to start collecting.'));right.append(discoveries);
 const footer=node('footer',null,'coastal-passport-footer'),continueButton=makeButton(state.complete&&['good','bad'].includes(state.cardPhase)?'Choose round cards →':'Return to map →',close);continueButton.className='coastal-passport-continue';footer.append(continueButton,node('small','GEOGRAPHY TAKES YOU FURTHER'));content.append(left,right,footer);
}
function routeSketch(state,best,stops,lineStops,node){const canvas=node('canvas',null,'coastal-passport-route-map');canvas.width=640;canvas.height=240;canvas.setAttribute('role','img');canvas.setAttribute('aria-label',best?'Route through '+best.stops.map(id=>stops[id].name).join(', '):'Your connected cities');const ctx=canvas.getContext('2d'),nodes=best?.stops??[...new Set(state.links.flatMap(lineStops))];ctx.fillStyle='#c9dfe1';ctx.fillRect(0,0,640,240);if(!nodes.length)return canvas;const points=nodes.map(id=>stops[id]),minX=Math.min(...points.map(p=>p.x)),minY=Math.min(...points.map(p=>p.y)),scale=Math.min(480/Math.max(1,Math.max(...points.map(p=>p.x))-minX),130/Math.max(1,Math.max(...points.map(p=>p.y))-minY)),position=p=>({x:80+(p.x-minX)*scale,y:55+(p.y-minY)*scale});for(const region of regions.filter(r=>r.round<=state.round)){ctx.beginPath();for(const ring of regionShapes[region.id]){ring.forEach(([lon,lat],i)=>{const v=position(project(lon,lat));ctx[i?'lineTo':'moveTo'](v.x,v.y);});ctx.closePath();}ctx.fillStyle=region.colour;ctx.fill();ctx.strokeStyle='#94ad90';ctx.lineWidth=1;ctx.stroke();}ctx.strokeStyle=lineColour(state.links[best?.index??0]?.slot??0);ctx.lineWidth=7;ctx.lineJoin='round';ctx.beginPath();points.forEach((p,i)=>{const v=position(p);ctx[i?'lineTo':'moveTo'](v.x,v.y);});ctx.stroke();for(const p of points){const v=position(p);ctx.beginPath();ctx.arc(v.x,v.y,9,0,Math.PI*2);ctx.fillStyle='#fffaf0';ctx.fill();ctx.strokeStyle='#164955';ctx.lineWidth=3;ctx.stroke();ctx.font='600 20px system-ui';ctx.textAlign='center';ctx.fillStyle='#164955';ctx.fillText(p.name,v.x,v.y+33);}return canvas;}
